{"path":"contact.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Connect — {{BUSINESS_NAME}}</title>
  <style>
    :root{
      --bg:#0f1221; --card:#10131c; --muted:#9aa0b1; --accent:#9be7b8; --accent-2:#c7b3ff; --glass: rgba(255,255,255,0.04);
      --radius:14px; --glass-2: rgba(255,255,255,0.02);
      --sans: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial;
    }
    html,body{height:100%;margin:0;font-family:var(--sans);background:radial-gradient(1200px 600px at 10% 10%, rgba(199,179,255,0.06), transparent), linear-gradient(180deg,#07070b,#0b0d12 45%,#0f1221 100%);color:#e9eef6}
    .site{min-height:100%;display:flex;flex-direction:column}
    header{display:flex;align-items:center;justify-content:space-between;padding:22px 28px;background:linear-gradient(180deg, rgba(255,255,255,0.02), transparent);backdrop-filter: blur(6px)}
    .brand{display:flex;gap:14px;align-items:center}
    .logo{width:48px;height:48px;border-radius:12px;background:linear-gradient(135deg,var(--accent),var(--accent-2));display:grid;place-items:center;font-weight:700;color:#08201a}
    .title{font-size:15px;letter-spacing:0.2px}
    nav a{color:var(--muted);margin-left:18px;text-decoration:none;font-size:14px}
    nav a:hover{color:var(--accent)}
    main{flex:1;padding:36px;display:grid;grid-template-columns:1fr 420px;gap:28px}
    .hero{background:linear-gradient(180deg, rgba(255,255,255,0.02), transparent);border-radius:var(--radius);padding:28px;box-shadow:0 6px 30px rgba(2,6,23,0.6);position:relative;overflow:hidden}
    .hero:before{content:"";position:absolute;inset:0;opacity:0.06;background-image:url('assets/img/pattern.svg');mix-blend-mode:overlay}
    h1{margin:0 0 10px 0;font-size:26px}
    p.lead{margin:0;color:var(--muted);line-height:1.5}

    /* Proof Gallery */
    .proof{margin-top:22px;padding:16px;border-radius:12px;background:linear-gradient(180deg,var(--glass),var(--glass-2));display:flex;flex-direction:column;gap:12px}
    .testimonial{min-height:120px;display:flex;flex-direction:column;gap:10px;opacity:0;transform:translateY(12px);transition:all 420ms ease}
    .testimonial.active{opacity:1;transform:none}
    .quote{font-size:15px;color:#e6eef8}
    .who{font-size:13px;color:var(--muted)}
    .badges{display:flex;gap:8px;align-items:center}
    .badge{display:inline-flex;align-items:center;gap:8px;padding:8px 10px;border-radius:10px;background:rgba(255,255,255,0.03);cursor:default}
    .badge svg{width:18px;height:18px;display:block}
    .badge .tip{position:relative}
    .badge .tip:focus, .badge .tip:hover{outline:none}
    .tooltip{position:absolute;left:50%;transform:translateX(-50%);bottom:calc(100% + 8px);background:#0b0d12;color:var(--muted);padding:8px 10px;border-radius:8px;font-size:12px;border:1px solid rgba(255,255,255,0.03);white-space:nowrap;opacity:0;pointer-events:none;transition:all 160ms ease}
    .badge:hover .tooltip, .badge:focus-within .tooltip{opacity:1;pointer-events:auto}

    /* Sidebar */
    aside{position:sticky;top:28px;height:fit-content}
    .card{background:linear-gradient(180deg, rgba(255,255,255,0.02), transparent);padding:18px;border-radius:12px}
    .contact-form{display:flex;flex-direction:column;gap:10px}
    .field{display:flex;flex-direction:column}
    label{font-size:13px;color:var(--muted)}
    input,textarea,select{margin-top:6px;padding:10px 12px;border-radius:10px;border:1px solid rgba(255,255,255,0.03);background:transparent;color:var(--muted);resize:vertical}
    button.primary{margin-top:8px;padding:10px 12px;border-radius:10px;border:none;background:linear-gradient(90deg,var(--accent),var(--accent-2));color:#052018;font-weight:700;cursor:pointer}
    .meta{font-size:13px;color:var(--muted);margin-top:8px}

    /* Pricing Comparator */
    .pricing{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:18px}
    .plan{background:linear-gradient(180deg, rgba(255,255,255,0.02), transparent);padding:14px;border-radius:12px}
    .toggle{display:flex;align-items:center;gap:10px;background:rgba(255,255,255,0.02);padding:8px;border-radius:999px;width:max-content}
    .switch{width:46px;height:26px;background:rgba(255,255,255,0.03);border-radius:999px;position:relative;cursor:pointer}
    .dot{width:18px;height:18px;background:#fff;border-radius:50%;position:absolute;top:4px;left:4px;transition:all 220ms ease;box-shadow:0 6px 18px rgba(8,16,16,0.25)}
    .switch.on{background:linear-gradient(90deg,var(--accent),var(--accent-2))}
    .switch.on .dot{left:24px;background:#052018}
    .price{font-size:22px;font-weight:700;color:#e8f9ee}
    .small{font-size:13px;color:var(--muted)}

    footer{padding:20px 28px;color:var(--muted);font-size:13px}

    @media (max-width:880px){main{grid-template-columns:1fr;padding:20px}aside{position:static}nav a{display:none}}
  </style>
</head>
<body>
  <div class="site">
    <header>
      <div class="brand"><div class="logo">HM</div><div class="title">Connect · {{BUSINESS_NAME}}</div></div>
      <nav aria-label="Main navigation">
        <a href="index.html">Home</a>
        <a href="approach.html">How we work</a>
        <a href="services.html">Offerings</a>
        <a href="conditions.html">Conditions</a>
        <a href="about.html">Stories</a>
        <a href="book.html">Book</a>
        <a href="contact.html">Connect</a>
      </nav>
    </header>

    <main>
      <section class="hero" aria-labelledby="contact-hero">
        <h1 id="contact-hero">Reach out — a short path to thoughtful care</h1>
        <p class="lead">If you have questions, want to ask about suitability, or need help deciding which pathway to begin, send a note. We listen to the whole picture, and then co-create next steps you can try.</p>

        <div class="proof" aria-live="polite">
          <div id="testimonials">
            <div class="testimonial active">
              <div class="quote">"A small set of steady changes that actually fit my schedule — I felt seen and supported through the process."</div>
              <div class="who">— L., freelance designer</div>
            </div>
            <div class="testimonial">
              <div class="quote">"Insightful assessments and practical routines helped me manage flare-ups without feeling overwhelmed."</div>
              <div class="who">— R., parent & teacher</div>
            </div>
            <div class="testimonial">
              <div class="quote">"Care that looked at patterns rather than quick fixes. The plan was realistic and steady."</div>
              <div class="who">— S., small business owner</div>
            </div>
          </div>

          <div class="badges" aria-hidden="false">
            <div class="badge" tabindex="0">
              <svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M12 2l3 6 6 .5-4.5 4L18 22l-6-3-6 3 .5-9.5L2 8.5 8 8 12 2z" fill="#c7b3ff"/></svg>
              <div class="tip">
                Accreditation
                <div class="tooltip">Member of regional integrative networks</div>
              </div>
            </div>
            <div class="badge" tabindex="0">
              <svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><circle cx="12" cy="12" r="10" fill="#9be7b8"/></svg>
              <div class="tip">
                Community Trust
                <div class="tooltip">Five-year local practice with community referrals</div>
              </div>
            </div>
            <div class="badge" tabindex="0">
              <svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><rect x="3" y="3" width="18" height="18" rx="4" fill="#ffd9b3"/></svg>
              <div class="tip">
                Published Case Notes
                <div class="tooltip">Selected case notes & reflections available with consent</div>
              </div>
            </div>
          </div>

        </div>

        <div style="margin-top:18px;display:flex;gap:12px;align-items:center">
          <a href="book.html" class="primary-cta" style="padding:10px 14px;border-radius:10px;background:linear-gradient(90deg,var(--accent),var(--accent-2));color:#04201a;font-weight:700;text-decoration:none">{{PRIMARY_CTA_LABEL}}</a>
          <a href="#contact-form" style="color:var(--muted);text-decoration:none">Message us</a>
        </div>

        <!-- Pricing comparators embedded in hero for context -->
        <div class="pricing" aria-hidden="false">
          <div class="plan">
            <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px">
              <div>
                <div class="small">Starter Pathway</div>
                <div class="price" data-month="89" data-package="240">$<span class="num">89</span><span class="small"> / mo</span></div>
              </div>
              <div>
                <div class="toggle">
                  <div class="small">Monthly</div>
                  <div class="switch" role="switch" aria-checked="true" tabindex="0"></div>
                </div>
              </div>
            </div>
            <div class="small">Weekly check-ins for the first month, plus a personalized plan.</div>
          </div>

          <div class="plan">
            <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px">
              <div>
                <div class="small">Reset Package</div>
                <div class="price" data-month="220" data-package="600">$<span class="num">220</span><span class="small"> / mo</span></div>
              </div>
              <div>
                <div class="toggle">
                  <div class="small">Monthly</div>
                  <div class="switch" role="switch" aria-checked="true" tabindex="0"></div>
                </div>
              </div>
            </div>
            <div class="small">Three-month plan with extended check-ins, labs and case notes.</div>
          </div>
        </div>

      </section>

      <aside>
        <div class="card">
          <div style="font-weight:700">Get in touch</div>
          <div class="meta">Call or message. We aim to reply within two business days. No guaranteed outcomes; a collaborative approach to exploring options.</div>
          <div style="margin-top:12px;font-weight:700">Phone</div>
          <div class="meta">{{PHONE}}</div>
          <div style="margin-top:12px;font-weight:700">Email</div>
          <div class="meta">{{EMAIL}}</div>

          <form id="contact-form" class="contact-form" onsubmit="submitForm(event)">
            <div class="field"><label for="name">Name</label><input id="name" name="name" required placeholder="Your name"></div>
            <div class="field"><label for="email">Email</label><input id="email" name="email" type="email" required placeholder="you@example.com"></div>
            <div class="field"><label for="reason">Reason for contact</label><select id="reason" name="reason"><option>Ask about services</option><option>Discuss suitability</option><option>Billing or insurance</option><option>Other</option></select></div>
            <div class="field"><label for="message">Message</label><textarea id="message" name="message" rows="4" placeholder="A brief note about what you'd like help with"></textarea></div>
            <button class="primary" type="submit">Send inquiry</button>
          </form>
        </div>

        <div style="height:12px"></div>

        <div class="card">
          <div style="font-weight:700">Quick booking</div>
          <div class="meta">If you'd like to book a brief intake, choose a slot on the booking page.</div>
          <a href="book.html" style="display:inline-block;margin-top:10px;padding:10px 12px;border-radius:10px;background:rgba(255,255,255,0.03);color:var(--muted);text-decoration:none">Open booking</a>
        </div>
      </aside>
    </main>

    <footer>
      <div>Serving {{CITY}}, {{STATE}} • For non-urgent inquiries only. Not medical advice; educational and supportive services.</div>
    </footer>
  </div>

  <script>
    // Rotating testimonials
    (function(){
      const container = document.getElementById('testimonials');
      const items = Array.from(container.children);
      let idx = 0;
      function show(i){
        items.forEach((el, n)=> el.classList.toggle('active', n===i));
      }
      function next(){ idx = (idx+1) % items.length; show(idx); }
      // advance every 5s, pause on hover
      let timer = setInterval(next, 5000);
      container.addEventListener('mouseenter', ()=> clearInterval(timer));
      container.addEventListener('mouseleave', ()=> timer = setInterval(next,5000));
      // keyboard controls
      container.addEventListener('keydown', (e)=>{
        if(e.key === 'ArrowRight') next();
        if(e.key === 'ArrowLeft'){ idx = (idx-1+items.length)%items.length; show(idx); }
      });
    })();

    // Pricing comparator: two instances in the page
    (function(){
      const switches = Array.from(document.querySelectorAll('.switch'));
      switches.forEach(sw=>{
        // derive related price element: traverse up to .plan then find .price
        const plan = sw.closest('.plan');
        const priceEl = plan.querySelector('.price .num');
        const perLabel = plan.querySelector('.price .small');
        const from = Number(priceEl.textContent.trim());
        const month = Number(plan.querySelector('.price').dataset.month);
        const pack = Number(plan.querySelector('.price').dataset.package);
        let state = true; // true = monthly
        function animateValue(el, start, end, duration){
          let startTime = null;
          function step(ts){
            if(!startTime) startTime = ts;
            const progress = Math.min((ts - startTime) / duration, 1);
            const val = Math.round(start + (end - start) * progress);
            el.textContent = val;
            if(progress < 1) requestAnimationFrame(step);
          }
          requestAnimationFrame(step);
        }
        function toggle(toMonthly){
          const start = Number(priceEl.textContent);
          const end = toMonthly ? month : pack;
          perLabel.textContent = toMonthly ? ' / mo' : ' total';
          animateValue(priceEl, start, end, 420);
          sw.classList.toggle('on', toMonthly);
          sw.setAttribute('aria-checked', toMonthly);
        }
        sw.addEventListener('click', ()=>{ state = !state; toggle(state); });
        sw.addEventListener('keydown', (e)=>{ if(e.key==='Enter' || e.key===' ') { e.preventDefault(); state = !state; toggle(state); } });
        // initialize: monthly on
        toggle(true);
      });
    })();

    // Simple form handler
    function submitForm(e){
      e.preventDefault();
      const form = e.target;
      const data = {name: form.name.value, email: form.email.value, reason: form.reason.value, message: form.message.value};
      // local demo: show a friendly message
      alert('Thanks — your message has been noted. We will respond to ' + data.email + '.');
      form.reset();
    }
  </script>
</body>
</html>"} 
{"path":"README.md","content":"Contact page and project notes

Files in this bundle chunk:
